//! # FieldCaptureProgram
//!
//! Generates eBPF bytecode that reads specified sk_buff fields and writes
//! them into a pre-allocated event section. The generated bytecode replaces
//! a placeholder `call` instruction in the SKB hook at BPF load time, using
//! the same injection mechanism as the existing metafilter.
//!
//! ## Calling convention
//!
//! The injected code receives:
//! - R1 = sk_buff pointer
//! - R2 = section data pointer (past the n_fields byte)
//!
//! Callee-saved registers used:
//! - R6 = preserved sk_buff pointer
//! - R7 = current struct base (reset to R6 per field)
//! - R8 = preserved section data pointer
//!
//! Stack usage:
//! - FP-8: 8-byte scratch for scalar reads and pointer dereferences
//! - FP-8-MAX_STR_LEN: scratch for string reads (up to META_TARGET_MAX bytes)
//!
//! ## Per-field slot layout
//!
//! Each field occupies a variable-size slot in the section:
//! ```text
//! [ u8 valid ] [ u8 pad ] [ value bytes (1/2/4/8 for scalars, up to 32 for strings) ]
//! ```
//! Slot offsets are compile-time constants baked into the generated bytecode.

use anyhow::{bail, ensure, Result};

use super::filter::{LoadCtx, PtrHop, ResolvedField, SliceSpec};
use crate::core::{
    bpf_sys,
    filters::packets::{
        bpf_common::*,
        ebpf::{eBpfProg, BpfReg},
        ebpfinsn::*,
    },
};

/// Maximum number of fields that can be captured.
#[allow(dead_code)]
pub(crate) const MAX_CAPTURE_FIELDS: usize = 16;

/// Maximum string length for captured string fields.
#[allow(dead_code)]
const MAX_STR_LEN: usize = 32;

/// Header size per slot: valid byte + pad byte.
#[allow(dead_code)]
pub(crate) const SLOT_HEADER_SIZE: usize = 2;

/// A generated eBPF program that captures sk_buff fields into an event section.
#[allow(dead_code)]
pub(crate) struct FieldCaptureProgram {
    prog: eBpfProg,
    /// Byte offset of each field's slot within the section data area.
    slot_offsets: Vec<usize>,
    /// Total section payload size (including the n_fields byte).
    total_section_size: usize,
}

#[allow(dead_code)]
impl FieldCaptureProgram {
    /// Generate capture bytecode for the given resolved fields.
    pub(crate) fn generate(fields: &[ResolvedField]) -> Result<Self> {
        ensure!(
            fields.len() <= MAX_CAPTURE_FIELDS,
            "too many fields (max {MAX_CAPTURE_FIELDS}, got {})",
            fields.len()
        );

        // Compute slot offsets (variable size per field).
        let mut slot_offsets = Vec::with_capacity(fields.len());
        let mut offset = 0;
        for field in fields {
            slot_offsets.push(offset);
            let value_size =
                Self::field_value_size_with_slice(&field.load, field.slice.as_ref())?;
            offset += SLOT_HEADER_SIZE + value_size;
        }

        // Total section size: 1 byte for n_fields + all slots.
        let total_section_size = 1 + offset;

        let mut prog = eBpfProg::new();

        // Preamble: save arguments to callee-saved registers.
        // R6 = R1 (skb pointer)
        prog.add(eBpfInsn::mov(MovInfo::Reg {
            src: BpfReg::R1,
            dst: BpfReg::R6,
        }));
        // R8 = R2 (section data pointer)
        prog.add(eBpfInsn::mov(MovInfo::Reg {
            src: BpfReg::R2,
            dst: BpfReg::R8,
        }));

        // Generate per-field capture blocks.
        // We collect jump-to-next-field positions for backpatching.
        let mut next_field_jumps: Vec<Vec<usize>> = Vec::new();

        for (idx, field) in fields.iter().enumerate() {
            let value_size =
                Self::field_value_size_with_slice(&field.load, field.slice.as_ref())?;
            let field_jumps = Self::emit_field_capture(
                &mut prog,
                field,
                slot_offsets[idx] as i16,
                value_size,
            )?;
            next_field_jumps.push(field_jumps);
        }

        // Backpatch: each field's failure jumps point to the start of the
        // next field block (or the epilogue for the last field).
        let epilogue_pos = prog.len();
        for (idx, jumps) in next_field_jumps.iter().enumerate() {
            let target = if idx + 1 < fields.len() {
                // Find the start of the next field block.
                // We need to know where each field block starts.
                // Since we can't easily track this during emission,
                // we use a different approach: patch to epilogue and
                // let subsequent fields naturally follow.
                epilogue_pos
            } else {
                epilogue_pos
            };

            for &jump_pos in jumps {
                let insn = prog.get_raw_insn_mut(jump_pos)?;
                if target > jump_pos {
                    insn.set_off_raw(i16::try_from(target - jump_pos - 1)?);
                }
            }
        }

        // Actually, we need a better approach for backpatching between
        // field blocks. Let me restructure: track block boundaries.
        // Re-generate with block boundary tracking.

        let mut prog = eBpfProg::new();

        // Preamble
        prog.add(eBpfInsn::mov(MovInfo::Reg {
            src: BpfReg::R1,
            dst: BpfReg::R6,
        }));
        prog.add(eBpfInsn::mov(MovInfo::Reg {
            src: BpfReg::R2,
            dst: BpfReg::R8,
        }));

        // Track block starts and failure jumps.
        let mut block_starts: Vec<usize> = Vec::new();
        let mut all_fail_jumps: Vec<Vec<usize>> = Vec::new();

        for (idx, field) in fields.iter().enumerate() {
            block_starts.push(prog.len());
            let value_size =
                Self::field_value_size_with_slice(&field.load, field.slice.as_ref())?;
            let fail_jumps = Self::emit_field_capture(
                &mut prog,
                field,
                slot_offsets[idx] as i16,
                value_size,
            )?;
            all_fail_jumps.push(fail_jumps);
        }

        let epilogue_pos = prog.len();

        // Epilogue: R0 = 0, return.
        prog.add(eBpfInsn::mov(MovInfo::Imm {
            dst: BpfReg::R0,
            imm: 0,
        }));

        // Backpatch failure jumps: each field's failures jump to the
        // next field's block start, or to the epilogue for the last field.
        for (idx, fail_jumps) in all_fail_jumps.iter().enumerate() {
            let target = if idx + 1 < fields.len() {
                block_starts[idx + 1]
            } else {
                epilogue_pos
            };

            for &jump_pos in fail_jumps {
                let insn = prog.get_raw_insn_mut(jump_pos)?;
                insn.set_off_raw(i16::try_from(target - jump_pos - 1)?);
            }
        }

        // Test support: add exit instruction so rbpf can execute it.
        #[cfg(test)]
        prog.add(eBpfInsn::exit());

        Ok(Self {
            prog,
            slot_offsets,
            total_section_size,
        })
    }

    /// Returns the total section payload size (including the n_fields byte).
    pub(crate) fn section_size(&self) -> u16 {
        self.total_section_size as u16
    }

    /// Returns the slot offsets for each field.
    pub(crate) fn slot_offsets(&self) -> &[usize] {
        &self.slot_offsets
    }

    /// Returns the generated bytecode as raw bytes.
    pub(crate) fn to_bytes(&self) -> Vec<u8> {
        self.prog.to_bytes()
    }

    /// Compute the value size in bytes for a field's slot in the section.
    /// Scalars and bitfields are always stored as 8 bytes (u64) for
    /// simplicity and alignment. Strings use their actual length.
    /// Byte slices use the user-specified length.
    pub(crate) fn field_value_size(load: &LoadCtx) -> Result<usize> {
        Self::field_value_size_with_slice(load, None)
    }

    /// Like `field_value_size` but also handles the slice override.
    pub(crate) fn field_value_size_with_slice(
        load: &LoadCtx,
        slice: Option<&SliceSpec>,
    ) -> Result<usize> {
        if let Some(sl) = slice {
            // Slice: store exactly `length` bytes.
            return Ok(sl.length as usize);
        }
        if load.is_arr() || (load.is_ptr() && load.is_byte()) {
            // String/char array: cap at MAX_STR_LEN.
            Ok(MAX_STR_LEN.min(load.nmemb as usize))
        } else if load.is_num() || load.bf_size > 0 {
            // All scalars and bitfields stored as u64.
            Ok(8)
        } else {
            bail!("unsupported field type for capture")
        }
    }

    /// Compute the read size in bytes for bpf_probe_read_kernel.
    /// This is the actual type size, not the slot size.
    fn field_read_size(load: &LoadCtx) -> Result<usize> {
        if load.bf_size > 0 {
            let total_bits = (load.offt % 8) as u32 + load.bf_size as u32;
            let bytes = total_bits.div_ceil(8) as usize;
            Ok(bytes.min(8))
        } else if load.is_byte() {
            Ok(1)
        } else if load.is_short() {
            Ok(2)
        } else if load.is_int() {
            Ok(4)
        } else if load.is_long() {
            Ok(8)
        } else {
            bail!("unsupported field type for capture read")
        }
    }

    /// Emit a complete capture block for one field. Returns a list of
    /// instruction positions that contain forward jumps to be backpatched
    /// to point to the next field's block start (failure path).
    fn emit_field_capture(
        prog: &mut eBpfProg,
        field: &ResolvedField,
        slot_offset: i16,
        value_size: usize,
    ) -> Result<Vec<usize>> {
        let mut fail_jumps: Vec<usize> = Vec::new();

        // Reset R7 = R6 (struct base = skb).
        prog.add(eBpfInsn::mov(MovInfo::Reg {
            src: BpfReg::R6,
            dst: BpfReg::R7,
        }));

        // Walk pointer hops.
        for hop in &field.ptr_hops {
            Self::emit_pointer_hop(prog, hop, slot_offset, &mut fail_jumps)?;
        }

        // Read the leaf value.
        if let Some(sl) = &field.slice {
            // Byte slice: dereference the pointer field then read `length`
            // bytes at `offset` from the pointer value.
            Self::emit_slice_capture(
                prog,
                sl,
                &field.load,
                slot_offset,
                value_size,
                &mut fail_jumps,
            )?;
        } else if field.load.is_arr() || (field.load.is_ptr() && field.load.is_byte()) {
            Self::emit_string_capture(
                prog,
                &field.load,
                slot_offset,
                value_size,
                &mut fail_jumps,
            )?;
        } else {
            Self::emit_scalar_capture(
                prog,
                &field.load,
                slot_offset,
                value_size,
                &mut fail_jumps,
            )?;
        }

        Ok(fail_jumps)
    }

    /// Emit a pointer dereference: read the pointer at R7+byte_offset into
    /// R7, applying mask if set. On failure, mark slot invalid and jump to
    /// the next field.
    fn emit_pointer_hop(
        prog: &mut eBpfProg,
        hop: &PtrHop,
        slot_offset: i16,
        fail_jumps: &mut Vec<usize>,
    ) -> Result<()> {
        // bpf_probe_read_kernel(FP-8, 8, R7 + byte_offset)
        prog.add_multi(&[
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::FP,
                dst: BpfReg::ARG1,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG1,
                    imm: -8,
                },
            ),
            eBpfInsn::mov(MovInfo::Imm {
                dst: BpfReg::ARG2,
                imm: 8,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::R7,
                    imm: hop.byte_offset as i32,
                },
            ),
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::R7,
                dst: BpfReg::ARG3,
            }),
            eBpfInsn::call(bpf_sys::bpf_func_id::BPF_FUNC_probe_read_kernel as u32),
        ]);

        // Check success: if R0 != 0, mark invalid and jump to next field.
        prog.add(eBpfInsn::jmp(
            eBpfJmpOpExt::Bpf(BpfJmpOp::Eq),
            JmpInfo::Imm {
                dst: BpfReg::R0,
                off: 2,
                imm: 0,
            },
        ));
        // Mark slot invalid.
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 0,
            },
            BpfSize::Byte,
        ));
        fail_jumps.push(prog.len());
        prog.add(eBpfInsn::jmp_a(0)); // backpatched later

        // Load the pointer from FP-8 into R7.
        prog.add(eBpfInsn::ld(
            LdInfo::Reg {
                src: BpfReg::FP,
                dst: BpfReg::R7,
                off: -8,
            },
            BpfSize::Double,
        ));

        // Apply mask if set.
        if hop.mask > 0 {
            // Build the mask in R5 and AND with R7.
            prog.add(eBpfInsn::mov(MovInfo::Imm {
                dst: BpfReg::R5,
                imm: (hop.mask >> 32) as i32,
            }));
            prog.add(eBpfInsn::alu(
                BpfAluOp::Lsh,
                AluInfo::Imm {
                    dst: BpfReg::R5,
                    imm: 32,
                },
            ));
            prog.add(eBpfInsn::alu(
                BpfAluOp::Or,
                AluInfo::Imm {
                    dst: BpfReg::R5,
                    imm: (hop.mask & 0xffffffff) as i32,
                },
            ));
            prog.add(eBpfInsn::alu(
                BpfAluOp::And,
                AluInfo::Reg {
                    src: BpfReg::R5,
                    dst: BpfReg::R7,
                },
            ));
        }

        // Null check: if R7 == 0, mark invalid and jump.
        prog.add(eBpfInsn::jmp(
            eBpfJmpOpExt::eBpf(eBpfJmpOp::Ne),
            JmpInfo::Imm {
                dst: BpfReg::R7,
                off: 2,
                imm: 0,
            },
        ));
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 0,
            },
            BpfSize::Byte,
        ));
        fail_jumps.push(prog.len());
        prog.add(eBpfInsn::jmp_a(0)); // backpatched later

        Ok(())
    }

    /// Emit bytecode to capture a scalar field (u8/u16/u32/u64/i*) into
    /// the section slot.
    fn emit_scalar_capture(
        prog: &mut eBpfProg,
        load: &LoadCtx,
        slot_offset: i16,
        _value_size: usize,
        fail_jumps: &mut Vec<usize>,
    ) -> Result<()> {
        let byte_offset = load.offt / 8;
        let read_size = Self::field_read_size(load)?;

        // bpf_probe_read_kernel(FP-8, read_size, R7 + byte_offset)
        prog.add_multi(&[
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::FP,
                dst: BpfReg::ARG1,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG1,
                    imm: -8,
                },
            ),
            eBpfInsn::mov(MovInfo::Imm {
                dst: BpfReg::ARG2,
                imm: read_size as i32,
            }),
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::R7,
                dst: BpfReg::ARG3,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG3,
                    imm: byte_offset as i32,
                },
            ),
            eBpfInsn::call(bpf_sys::bpf_func_id::BPF_FUNC_probe_read_kernel as u32),
        ]);

        // Check success.
        prog.add(eBpfInsn::jmp(
            eBpfJmpOpExt::Bpf(BpfJmpOp::Eq),
            JmpInfo::Imm {
                dst: BpfReg::R0,
                off: 2,
                imm: 0,
            },
        ));
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 0,
            },
            BpfSize::Byte,
        ));
        fail_jumps.push(prog.len());
        prog.add(eBpfInsn::jmp_a(0)); // backpatched later

        // Load value from stack.
        let bpf_size = Self::size_to_bpf(read_size)?;
        prog.add(eBpfInsn::ld(
            LdInfo::Reg {
                src: BpfReg::FP,
                dst: BpfReg::R5,
                off: -8,
            },
            bpf_size,
        ));

        // Handle bitfield: shift to extract the field.
        if load.bf_size > 0 {
            let bf_rshf = 64 - load.bf_size as i32;
            let bf_lshf = bf_rshf - (load.offt % 8) as i32;

            prog.add(eBpfInsn::alu(
                BpfAluOp::Lsh,
                AluInfo::Imm {
                    dst: BpfReg::R5,
                    imm: bf_lshf,
                },
            ));

            let shift_op = if load.is_signed() {
                BpfAluOp::Arsh
            } else {
                BpfAluOp::Rsh
            };
            prog.add(eBpfInsn::alu(
                shift_op,
                AluInfo::Imm {
                    dst: BpfReg::R5,
                    imm: bf_rshf,
                },
            ));
        }

        // Apply mask if set.
        if load.mask > 0 {
            prog.add_multi(&eBpfInsn::ld64_imm(BpfReg::R9, load.mask as i64));
            prog.add(eBpfInsn::alu(
                BpfAluOp::And,
                AluInfo::Reg {
                    src: BpfReg::R9,
                    dst: BpfReg::R5,
                },
            ));
        }

        // Mark slot as valid.
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 1,
            },
            BpfSize::Byte,
        ));

        // Store value into the section slot (at slot_offset + SLOT_HEADER_SIZE).
        let value_off = slot_offset + SLOT_HEADER_SIZE as i16;

        // Always store as 8 bytes (u64) for simplicity and alignment.
        prog.add(eBpfInsn::st(
            StInfo::Reg {
                src: BpfReg::R5,
                dst: BpfReg::R8,
                off: value_off,
            },
            BpfSize::Double,
        ));

        Ok(())
    }

    /// Emit bytecode to capture a string field into the section slot.
    fn emit_string_capture(
        prog: &mut eBpfProg,
        load: &LoadCtx,
        slot_offset: i16,
        value_size: usize,
        fail_jumps: &mut Vec<usize>,
    ) -> Result<()> {
        let byte_offset = load.offt / 8;
        let stack_scratch = -(8 + value_size as i32);

        // bpf_probe_read_kernel_str(FP+stack_scratch, value_size, R7+byte_offset)
        prog.add_multi(&[
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::FP,
                dst: BpfReg::ARG1,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG1,
                    imm: stack_scratch,
                },
            ),
            eBpfInsn::mov(MovInfo::Imm {
                dst: BpfReg::ARG2,
                imm: value_size as i32,
            }),
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::R7,
                dst: BpfReg::ARG3,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG3,
                    imm: byte_offset as i32,
                },
            ),
            eBpfInsn::call(bpf_sys::bpf_func_id::BPF_FUNC_probe_read_kernel_str as u32),
        ]);

        // Check success: bpf_probe_read_kernel_str returns > 0 on success.
        prog.add(eBpfInsn::jmp(
            eBpfJmpOpExt::eBpf(eBpfJmpOp::GtS),
            JmpInfo::Imm {
                dst: BpfReg::R0,
                off: 2,
                imm: 0,
            },
        ));
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 0,
            },
            BpfSize::Byte,
        ));
        fail_jumps.push(prog.len());
        prog.add(eBpfInsn::jmp_a(0)); // backpatched later

        // Mark slot as valid.
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 1,
            },
            BpfSize::Byte,
        ));

        // Copy string from stack scratch to section slot using 8-byte stores.
        let value_off = slot_offset + SLOT_HEADER_SIZE as i16;
        let n_qwords = value_size.div_ceil(8);
        for i in 0..n_qwords {
            let src_off = stack_scratch + (i * 8) as i32;
            let dst_off = value_off + (i * 8) as i16;

            prog.add(eBpfInsn::ld(
                LdInfo::Reg {
                    src: BpfReg::FP,
                    dst: BpfReg::R5,
                    off: src_off as i16,
                },
                BpfSize::Double,
            ));
            prog.add(eBpfInsn::st(
                StInfo::Reg {
                    src: BpfReg::R5,
                    dst: BpfReg::R8,
                    off: dst_off,
                },
                BpfSize::Double,
            ));
        }

        Ok(())
    }

    /// Emit bytecode to capture a byte slice from a pointer field.
    ///
    /// R7 is the struct base (skb, or previously dereferenced pointer for
    /// intermediate hops). `load.offt/8` is the byte offset of the pointer
    /// field within R7's struct.
    ///
    /// Steps:
    /// 1. Read the pointer value from R7 + load.offt/8 into FP-8.
    /// 2. Load the pointer into R5; NULL-check it.
    /// 3. Read `length` bytes from (R5 + slice.offset) directly into the
    ///    section slot value area (R8 + slot_offset + SLOT_HEADER_SIZE).
    ///    Writing directly to the event section avoids stack alignment issues.
    fn emit_slice_capture(
        prog: &mut eBpfProg,
        sl: &SliceSpec,
        load: &LoadCtx,
        slot_offset: i16,
        value_size: usize,
        fail_jumps: &mut Vec<usize>,
    ) -> Result<()> {
        let ptr_byte_offset = (load.offt / 8) as i32;
        let value_off = slot_offset + SLOT_HEADER_SIZE as i16;

        // Step 1: read the pointer value from R7+ptr_byte_offset into FP-8.
        prog.add_multi(&[
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::FP,
                dst: BpfReg::ARG1,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG1,
                    imm: -8,
                },
            ),
            eBpfInsn::mov(MovInfo::Imm {
                dst: BpfReg::ARG2,
                imm: 8,
            }),
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::R7,
                dst: BpfReg::ARG3,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG3,
                    imm: ptr_byte_offset,
                },
            ),
            eBpfInsn::call(bpf_sys::bpf_func_id::BPF_FUNC_probe_read_kernel as u32),
        ]);

        // Check probe_read success; mark invalid on failure.
        prog.add(eBpfInsn::jmp(
            eBpfJmpOpExt::Bpf(BpfJmpOp::Eq),
            JmpInfo::Imm {
                dst: BpfReg::R0,
                off: 2,
                imm: 0,
            },
        ));
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 0,
            },
            BpfSize::Byte,
        ));
        fail_jumps.push(prog.len());
        prog.add(eBpfInsn::jmp_a(0));

        // Step 2: load pointer value from FP-8 into R5, NULL-check.
        prog.add(eBpfInsn::ld(
            LdInfo::Reg {
                src: BpfReg::FP,
                dst: BpfReg::R5,
                off: -8,
            },
            BpfSize::Double,
        ));
        prog.add(eBpfInsn::jmp(
            eBpfJmpOpExt::eBpf(eBpfJmpOp::Ne),
            JmpInfo::Imm {
                dst: BpfReg::R5,
                off: 2,
                imm: 0,
            },
        ));
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 0,
            },
            BpfSize::Byte,
        ));
        fail_jumps.push(prog.len());
        prog.add(eBpfInsn::jmp_a(0));

        // Step 3: read `value_size` bytes from (R5 + slice.offset) directly
        // into the section slot value area. R8 points into the event ring
        // buffer section which is treated as mem by the verifier, so this
        // avoids all stack alignment issues.
        prog.add_multi(&[
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::R8,
                dst: BpfReg::ARG1,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG1,
                    imm: value_off as i32,
                },
            ),
            eBpfInsn::mov(MovInfo::Imm {
                dst: BpfReg::ARG2,
                imm: value_size as i32,
            }),
            eBpfInsn::mov(MovInfo::Reg {
                src: BpfReg::R5,
                dst: BpfReg::ARG3,
            }),
            eBpfInsn::alu(
                BpfAluOp::Add,
                AluInfo::Imm {
                    dst: BpfReg::ARG3,
                    imm: sl.offset as i32,
                },
            ),
            eBpfInsn::call(bpf_sys::bpf_func_id::BPF_FUNC_probe_read_kernel as u32),
        ]);

        // Check success; mark valid on success, invalid on failure.
        prog.add(eBpfInsn::jmp(
            eBpfJmpOpExt::Bpf(BpfJmpOp::Eq),
            JmpInfo::Imm {
                dst: BpfReg::R0,
                off: 2,
                imm: 0,
            },
        ));
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 0,
            },
            BpfSize::Byte,
        ));
        fail_jumps.push(prog.len());
        prog.add(eBpfInsn::jmp_a(0));

        // Mark slot as valid.
        prog.add(eBpfInsn::st(
            StInfo::Imm {
                dst: BpfReg::R8,
                off: slot_offset,
                imm: 1,
            },
            BpfSize::Byte,
        ));

        Ok(())
    }

    /// Convert a byte size to a BpfSize enum.
    fn size_to_bpf(size: usize) -> Result<BpfSize> {
        match size {
            1 => Ok(BpfSize::Byte),
            2 => Ok(BpfSize::Half),
            4 => Ok(BpfSize::Word),
            8 => Ok(BpfSize::Double),
            _ => {
                // For bitfields that span odd byte counts (e.g. 3 bytes),
                // round up to the next power of two size for the load.
                if size <= 2 {
                    Ok(BpfSize::Half)
                } else if size <= 4 {
                    Ok(BpfSize::Word)
                } else {
                    Ok(BpfSize::Double)
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::filters::meta::filter::resolve_fields;
    use crate::core::filters::{bpf_probe_read_kernel_helper, bpf_probe_read_kernel_str_helper};

    mod skb_gen {
        #![allow(warnings)]
        include!(concat!(env!("CARGO_MANIFEST_DIR"), "/test_data/skb_gen.rs"));
    }
    use skb_gen::{net_device, nf_conn, sk_buff};

    // Reuse the same init_sk_buff as the metafilter runtime tests.
    // Fields set:
    //   len = 2048, queue_mapping = 3, cloned = 1,
    //   pkt_type = 0b110, nf_trace = 1, ip_summed = 0b11,
    //   vlan_tci = 1234, dev.name = "verylongtruncat",
    //   _nfct = nf_conn_ptr | 2, nf_conn.mark = 3
    fn init_sk_buff() -> (sk_buff, Box<net_device>, Box<nf_conn>) {
        let mut skb: sk_buff = Default::default();
        let mut net_dev = Box::new(net_device::default());
        let mut nfct = Box::new(nf_conn::default());
        let name_bytes = "verylongtruncat".as_bytes();

        name_bytes
            .iter()
            .take(15)
            .enumerate()
            .for_each(|(i, &b)| net_dev.name[i] = b as ::std::os::raw::c_char);

        nfct.mark = 3;

        let nfct_ptr = &*nfct as *const nf_conn as u64;
        skb._nfct = nfct_ptr | 2;

        skb.len = 2048;
        skb.queue_mapping = 3;

        unsafe {
            skb.set_cloned(1);
            skb.__bindgen_anon_5
                .__bindgen_anon_1
                .as_mut()
                .__bindgen_anon_2
                .__bindgen_anon_1
                .vlan_tci = 1234;
            skb.__bindgen_anon_5
                .__bindgen_anon_1
                .as_mut()
                .set_ip_summed(0b11);
            skb.__bindgen_anon_5
                .__bindgen_anon_1
                .as_mut()
                .set_nf_trace(1);
            skb.__bindgen_anon_5
                .__bindgen_anon_1
                .as_mut()
                .set_pkt_type(0b110);
        }

        skb.__bindgen_anon_1.__bindgen_anon_1.__bindgen_anon_1.dev = &mut *net_dev;

        (skb, net_dev, nfct)
    }

    /// Execute capture bytecode against an in-memory sk_buff and return
    /// the section output buffer.
    ///
    /// The rbpf VM only allows writes to known memory regions. We pass the
    /// section output buffer as `mem` and load R2 from R1 (mem data ptr).
    /// However, rbpf's EbpfVmMbuff sets R1 = mbuff pointer, not mem.
    ///
    /// Strategy: use EbpfVmRaw which sets R1 = mem pointer (the section buf),
    /// and embed the sk_buff address as a ld64_imm for R1 instead.
    /// But that won't work either since probe_read_kernel reads from host
    /// memory which rbpf doesn't restrict.
    ///
    /// Actually, looking at the existing metafilter tests: they use
    /// EbpfVmMbuff and bpf_probe_read_kernel_helper which does a plain
    /// memcpy from host addresses. The VM only validates stores, not reads
    /// via helpers. So the issue is that stores to the section buffer (R8)
    /// are going to host addresses that rbpf doesn't know about.
    ///
    /// Fix: use EbpfVmFixedMbuff or EbpfVmRaw, or use the `mem` parameter
    /// as the section output and set R2 to point into it.
    fn run_capture(fields_str: &str, skb: &sk_buff) -> Vec<u8> {
        let resolved = resolve_fields(fields_str).unwrap();
        let capture = FieldCaptureProgram::generate(&resolved).unwrap();

        let section_data_size = capture.section_size() as usize - 1;

        // Use `mem` as the section output buffer. rbpf allows stores
        // to `mem` addresses. We prefix the capture bytecode with
        // instructions that set R2 from the mem base address.
        // rbpf doesn't directly expose the mem base to the program,
        // but we can use EbpfVmRaw where R1 = mem pointer.
        //
        // However, we need R1 = skb. So instead we:
        // 1. Use a combined buffer: [section_data | padding]
        // 2. Load the skb address via ld64_imm into R1
        // 3. Set R2 = mem base (section output)
        //
        // rbpf's EbpfVmRaw: R1 = pointer to mem data.
        // So R1 initially = section_buf. We save it to R2, then load skb addr into R1.

        let mut mem = vec![0u8; section_data_size];

        let skb_ptr = skb as *const _ as u64;
        let mut full_prog = eBpfProg::new();

        // R1 = mem base (section buf) from rbpf. Save to R2.
        full_prog.add(eBpfInsn::mov(MovInfo::Reg {
            src: BpfReg::R1,
            dst: BpfReg::R2,
        }));

        // Load skb host address into R1.
        full_prog.add_multi(&eBpfInsn::ld64_imm(BpfReg::R1, skb_ptr as i64));

        // Append the capture program.
        full_prog.append_prog(&capture.prog);

        let prog_bytes = full_prog.to_bytes();

        let mut vm = rbpf::EbpfVmRaw::new(Some(&prog_bytes)).unwrap();
        vm.register_helper(113, bpf_probe_read_kernel_helper)
            .unwrap();
        vm.register_helper(115, bpf_probe_read_kernel_str_helper)
            .unwrap();
        vm.execute_program(&mut mem).unwrap();

        mem
    }

    /// Read a scalar value from a section buffer at the given slot offset.
    fn read_slot_valid(buf: &[u8], slot_offset: usize) -> bool {
        buf[slot_offset] == 1
    }

    fn read_slot_u32(buf: &[u8], slot_offset: usize) -> u32 {
        let start = slot_offset + SLOT_HEADER_SIZE;
        u32::from_ne_bytes(buf[start..start + 4].try_into().unwrap())
    }

    fn read_slot_u16(buf: &[u8], slot_offset: usize) -> u16 {
        let start = slot_offset + SLOT_HEADER_SIZE;
        u16::from_ne_bytes(buf[start..start + 2].try_into().unwrap())
    }

    fn read_slot_string(buf: &[u8], slot_offset: usize) -> String {
        let start = slot_offset + SLOT_HEADER_SIZE;
        let bytes = &buf[start..];
        let end = bytes.iter().position(|&b| b == 0).unwrap_or(bytes.len());
        String::from_utf8_lossy(&bytes[..end]).to_string()
    }

    #[test]
    fn capture_scalar_u32() {
        let (skb, _net_dev, _nfct) = init_sk_buff();
        // len is set to 2048 in init_sk_buff
        let buf = run_capture("len", &skb);
        assert!(read_slot_valid(&buf, 0));
        assert_eq!(read_slot_u32(&buf, 0), 2048);
    }

    #[test]
    fn capture_scalar_u16() {
        let (skb, _net_dev, _nfct) = init_sk_buff();
        // queue_mapping is set to 3 in init_sk_buff
        let buf = run_capture("queue_mapping", &skb);
        assert!(read_slot_valid(&buf, 0));
        assert_eq!(read_slot_u16(&buf, 0), 3);
    }

    #[test]
    fn capture_string_through_ptr() {
        let (skb, _net_dev, _nfct) = init_sk_buff();
        let buf = run_capture("dev.name", &skb);
        assert!(read_slot_valid(&buf, 0));
        assert_eq!(read_slot_string(&buf, 0), "verylongtruncat");
    }

    #[test]
    fn capture_bitfield() {
        let (skb, _net_dev, _nfct) = init_sk_buff();
        // pkt_type is set to 0b110 = 6 in init_sk_buff
        let buf = run_capture("pkt_type", &skb);
        assert!(read_slot_valid(&buf, 0));
        // Stored as u64, read the first byte.
        let val = buf[SLOT_HEADER_SIZE];
        assert_eq!(val, 6);
    }

    #[test]
    fn capture_mask_and_cast() {
        let (skb, _net_dev, _nfct) = init_sk_buff();
        // _nfct = nf_conn_ptr | 2, nf_conn.mark = 3
        let buf = run_capture("_nfct:~0x7:nf_conn.mark", &skb);
        assert!(read_slot_valid(&buf, 0));
        assert_eq!(read_slot_u32(&buf, 0), 3);
    }

    #[test]
    fn capture_null_pointer() {
        let (mut skb, _net_dev, _nfct) = init_sk_buff();
        // Set dev to null.
        skb.__bindgen_anon_1.__bindgen_anon_1.__bindgen_anon_1.dev =
            std::ptr::null_mut();
        let buf = run_capture("dev.name", &skb);
        assert!(!read_slot_valid(&buf, 0));
    }

    #[test]
    fn capture_multiple_fields() {
        let (skb, _net_dev, _nfct) = init_sk_buff();
        // len (u32) and queue_mapping (u16)
        let resolved = resolve_fields("len, queue_mapping").unwrap();
        let capture = FieldCaptureProgram::generate(&resolved).unwrap();

        assert_eq!(capture.slot_offsets().len(), 2);
        // len: u32 → slot size = 2 + 8 = 10 (stored as u64)
        assert_eq!(capture.slot_offsets()[0], 0);
        assert_eq!(capture.slot_offsets()[1], 10);

        let buf = run_capture("len, queue_mapping", &skb);
        assert!(read_slot_valid(&buf, 0));
        assert_eq!(read_slot_u32(&buf, 0), 2048);
        assert!(read_slot_valid(&buf, 10));
        assert_eq!(read_slot_u16(&buf, 10), 3);
    }

    #[test]
    fn capture_section_size() {
        let resolved = resolve_fields("len, dev.name, queue_mapping").unwrap();
        let capture = FieldCaptureProgram::generate(&resolved).unwrap();

        // len: u32 → 2 + 8 = 10
        // dev.name: char[16] → 2 + 16 = 18
        // queue_mapping: u16 → 2 + 8 = 10
        // total data = 10 + 18 + 10 = 38
        // section size = 1 (n_fields) + 38 = 39
        let name_size = resolved[1].load.nmemb as usize;
        let expected = 1 + (2 + 8) + (2 + name_size) + (2 + 8);
        assert_eq!(capture.section_size() as usize, expected);
    }

    #[test]
    fn capture_data_slice() {
        let (mut skb, _net_dev, _nfct) = init_sk_buff();
        // Point skb.data at a known buffer so we can verify the slice.
        let payload: [u8; 16] = [
            0x45, 0x00, 0x00, 0x28, 0xde, 0xad, 0x40, 0x00,
            0x40, 0x06, 0x00, 0x00, 0x7f, 0x00, 0x00, 0x01,
        ];
        // SAFETY: we set skb.data to point at the payload array for the
        // duration of this test. rbpf's probe_read helper does a plain
        // memcpy so this is safe in a test context.
        skb.data = payload.as_ptr() as *mut u8;

        // Capture data[0:8]: first 8 bytes of the payload.
        let buf = run_capture("data[0:8]", &skb);
        assert!(read_slot_valid(&buf, 0), "slice capture should succeed");
        // Verify the first 4 bytes match the payload.
        let value_start = SLOT_HEADER_SIZE;
        assert_eq!(buf[value_start], 0x45, "first byte should be 0x45 (IPv4/IHL=5)");
        assert_eq!(buf[value_start + 1], 0x00);
    }

    #[test]
    fn capture_slice_section_size() {
        // data[4:16]: slot = 2 + 16 = 18; section = 1 + 18 = 19
        let resolved = resolve_fields("data[4:16]").unwrap();
        assert_eq!(resolved.len(), 1);
        assert_eq!(resolved[0].name, "data[4:16]");
        let capture = FieldCaptureProgram::generate(&resolved).unwrap();
        assert_eq!(capture.section_size() as usize, 1 + 2 + 16);
    }

    #[test]
    fn resolve_fields_slice_errors() {
        // Slice on a scalar field must be rejected.
        assert!(resolve_fields("len[0:4]").is_err());
        // Zero length rejected.
        assert!(resolve_fields("data[0:0]").is_err());
        // Exceeds MAX_SLICE_LEN.
        assert!(resolve_fields("data[0:65]").is_err());
        // Malformed syntax.
        assert!(resolve_fields("data[0]").is_err());
    }
}
